def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    with np.errstate(divide='ignore', invalid='ignore'):
        scores = 1.0 / (1.0 + np.maximum(0.0, -remaining))
    return np.where(remaining < 0, -np.inf, scores)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_buffer = 0.1 * bins
    scores = np.exp(-((remaining - optimal_buffer) ** 2) / (2 * (0.2 * np.maximum(bins, 1e-5)) ** 2))
    return np.where(remaining < 0, -np.inf, scores)

